25	/// Composes the contents of a single page/region. A region can have multiple
26	/// columns/subregions.
27	///
28	/// The composer is primarily concerned with layout of out-of-flow insertions
29	/// (floats and footnotes).  It does this in per-page and per-column loops that
30	/// rerun when a new float is added (since it affects the regions available to
31	/// the distributor).
32	///
33	/// To lay out the in-flow contents of individual subregions, the composer
34	/// invokes [distribution](distribute()).
35	pub fn compose(
36	    engine: &mut Engine,
37	    work: &mut Work,
38	    config: &Config,
39	    locator: Locator,
40	    regions: Regions,
41	) -> SourceResult<Frame> {
42	    Composer {
43	        engine,
44	        config,
45	        page_base: regions.base(),
46	        column: 0,
47	        page_insertions: Insertions::default(),
48	        column_insertions: Insertions::default(),
49	        column_balancing_height: None,
50	        work,
51	        footnote_spill: None,
52	        footnote_queue: vec![],
53	    }
54	    .page(locator, regions)
55	}
56	
57	/// State for composition.
58	///
59	/// Sadly, we need that many lifetimes because &mut references are invariant and
60	/// it would force the lifetimes of various things to be equal if they
61	/// shared a lifetime.
62	///
63	/// The only interesting lifetimes are 'a and 'b. See [Work] for more details
64	/// about them.
65	pub struct Composer<'a, 'b, 'x, 'y> {
66	    pub engine: &'x mut Engine<'y>,
67	    pub work: &'x mut Work<'a, 'b>,
68	    pub config: &'x Config<'x>,
69	    column: usize,
70	    page_base: Size,
71	    page_insertions: Insertions<'a, 'b>,
72	    column_insertions: Insertions<'a, 'b>,
73	    column_balancing_height: Option<Abs>,
74	    // These are here because they have to survive relayout (we could lose the
75	    // footnotes otherwise). For floats, we revisit them anyway, so it's okay to
76	    // use `work.floats` directly. This is not super clean; probably there's a
77	    // better way.
78	    footnote_spill: Option<std::vec::IntoIter<Frame>>,
79	    footnote_queue: Vec<Packed<FootnoteElem>>,
80	}
81	
82	impl<'a, 'b> Composer<'a, 'b, '_, '_> {
83	    /// Lay out a container/page region, including container/page insertions.
84	    fn page(mut self, locator: Locator, regions: Regions) -> SourceResult<Frame> {
85	        // This loop can restart region layout when requested to do so by a
86	        // `Stop`. This happens when there is a parent-scoped float.
87	        let checkpoint = self.work.clone();
88	        let output = loop {
89	            // Shrink the available space by the space used by page
90	            // insertions.
91	            let mut pod = regions;
92	            pod.size.y -= self.page_insertions.height();
93	
94	            match self.page_contents(locator.relayout(), pod) {
95	                Ok(frame) => break frame,
96	                Err(Stop::Finish(_)) => unreachable!(),
97	                Err(Stop::Relayout(PlacementScope::Column)) => unreachable!(),
98	                Err(Stop::Relayout(PlacementScope::Parent)) => {
99	                    *self.work = checkpoint.clone();
100	                }
101	                Err(Stop::Error(err)) => return Err(err),
102	            }
103	        };
104	        drop(checkpoint);
105	
106	        Ok(self.page_insertions.finalize(self.work, self.config, output, None))
107	    }
108	
109	    /// Lay out the inner contents of a container/page.
110	    fn page_contents(&mut self, locator: Locator, regions: Regions) -> FlowResult<Frame> {
111	        // No point in create column regions, if there's just one!
112	        if self.config.columns.count == 1 {
113	            return self.column(locator, regions).map(|(frame, _)| frame);
114	        }
115	
116	        // Create a backlog for multi-column layout.
117	        let column_height = regions.size.y;
118	        let backlog: Vec<_> = std::iter::once(&column_height)
119	            .chain(regions.backlog)
120	            .flat_map(|&h| std::iter::repeat_n(h, self.config.columns.count))
121	            .skip(1)
122	            .collect();
123	
124	        // Subregions for column layout.
125	        let mut inner = Regions {
126	            size: Size::new(self.config.columns.width, column_height),
127	            backlog: &backlog,
128	            expand: Axes::new(true, regions.expand.y),
129	            ..regions
130	        };
131	
132	        // The size of the merged frame hosting multiple columns.
133	        let size = Size::new(
134	            regions.size.x,
135	            if regions.expand.y { regions.size.y } else { Abs::zero() },
136	        );
137	
138	        let mut output = Frame::hard(size);
139	        let mut offset = Abs::zero();
140	        let mut locator = locator.split();
141	        let mut total_used_height = Abs::zero();
142	
143	        // Lay out the columns and stitch them together.
144	        for i in 0..self.config.columns.count {
145	            self.column = i;
146	            let (frame, used_height) = self.column(locator.next(&()), inner)?;
147	            total_used_height += used_height;
148	
149	            if !regions.expand.y {
150	                output.size_mut().y.set_max(frame.height());
151	            }
152	
153	            let width = frame.width();
154	            let x = if self.config.columns.dir == Dir::LTR {
155	                offset
156	            } else {
157	                regions.size.x - offset - width
158	            };
159	            offset += width + self.config.columns.gutter;
160	
161	            // During distribution, the baseline of the region is set to the
162	            // baseline of the first frame - e.g., the first paragraph line.
163	            // However, this does not propagate outwards unless we also update
164	            // the baseline of the column that region is in.
165	            if i == 0 && frame.has_baseline() {
166	                output.set_baseline(frame.baseline());
167	            }
168	
169	            output.push_frame(Point::with_x(x), frame);
170	            inner.next();
171	        }
172	
173	        // Column balancing with re-layout
174	        if self.config.columns.balanced && self.work.done() {
175	            let height = total_used_height / self.config.columns.count as f64;
176	            if self.column_balancing_height.is_none_or(|h| h < height) {
177	                self.column_balancing_height = Some(height);
178	                return Err(Stop::Relayout(PlacementScope::Parent));
179	            }
180	        }
181	
182	        Ok(output)
183	    }
184	
185	    /// Lay out a column, including column insertions.
186	    ///
187	    /// Returns a `FlowResult` containing a tuple of
188	    /// - `0`: The laid out frame.
189	    /// - `1`: The height actually used by the inner contents (used for column balancing logic).
190	    fn column(&mut self, locator: Locator, regions: Regions) -> FlowResult<(Frame, Abs)> {
191	        // Reset column insertion when starting a new column.
192	        self.column_insertions = Insertions::default();
193	
194	        // Process footnote spill.
195	        if let Some(spill) = self.work.footnote_spill.take() {
196	            self.footnote_spill(spill, regions.base())?;
197	        }
198	
199	        // This loop can restart column layout when requested to do so by a
200	        // `Stop`. This happens when there is a column-scoped float.
201	        let checkpoint = self.work.clone();
202	        let (inner, used_height) = loop {
203	            // Shrink the available space by the space used by column
204	            // insertions.
205	            let mut pod = regions;
206	            pod.size.y -= self.column_insertions.height();
207	
208	            // For column balancing, only consider space taken by floats, not footnotes
209	            let float_height = self.column_insertions.float_height();
210	            let balancing_target = if self.column < self.config.columns.count - 1 {
211	                self.column_balancing_height.map(|h| h - float_height)
212	            } else {
213	                None
214	            };
215	
216	            match self.column_contents(pod, balancing_target) {
217	                Ok((frame, used_height)) => break (frame, used_height + float_height),
218	                Err(Stop::Finish(_)) => unreachable!(),
219	                Err(Stop::Relayout(PlacementScope::Column)) => {
220	                    *self.work = checkpoint.clone();
221	                }
222	                err => return err,
223	            }
224	        };
225	        drop(checkpoint);
226	
227	        self.work.footnotes.extend(self.footnote_queue.drain(..));
228	        if let Some(spill) = self.footnote_spill.take() {
229	            self.work.footnote_spill = Some(spill);
230	        }
231	
232	        let insertions = std::mem::take(&mut self.column_insertions);
233	        let mut output = insertions.finalize(
234	            self.work,
235	            self.config,
236	            inner,
237	            self.column_balancing_height,
238	        );
239	
240	        // Lay out per-column line numbers.
241	        if let Some(line_config) = &self.config.line_numbers {
242	            layout_line_numbers(
243	                self.engine,
244	                self.config,
245	                line_config,
246	                locator,
247	                self.column,
248	                &mut output,
249	            )?;
250	        }
251	
252	        Ok((output, used_height))
253	    }
254	
255	    /// Lay out the inner contents of a column.
256	    ///
257	    /// Pending floats and footnotes are also laid out at this step. For those,
258	    /// however, we forbid footnote migration (moving the frame containing the
259	    /// footnote reference if the corresponding entry doesn't fit), allowing
260	    /// the footnote invariant to be broken, as it would require handling a
261	    /// [`Stop::Finish`] at this point, but that is exclusively handled by the
262	    /// distributor.
263	    fn column_contents(
264	        &mut self,
265	        regions: Regions,
266	        balancing_target: Option<Abs>,
267	    ) -> FlowResult<(Frame, Abs)> {
268	        // Process pending footnotes.
269	        for note in std::mem::take(&mut self.work.footnotes) {
270	            self.footnote(note, &mut regions.clone(), Abs::zero(), false)?;
271	        }
272	
273	        // Process pending floats.
274	        for placed in std::mem::take(&mut self.work.floats) {
275	            self.float(placed, &regions, false, false)?;
276	        }
277	
278	        distribute(self, regions, balancing_target)
279	    }
280	
281	    /// Lays out an item with floating placement.
282	    ///
283	    /// This is called from within [`distribute()`]. When the float fits, this
284	    /// returns an `Err(Stop::Relayout(..))`, which bubbles all the way through
285	    /// distribution and is handled in [`Self::page`] or [`Self::column`]
286	    /// (depending on `placed.scope`).
287	    ///
288	    /// When the float does not fit, it is queued into `work.floats`. The
289	    /// value of `clearance` indicates that between the float and flow content
290	    /// is needed --- it is set if there are already distributed items.
291	    ///
292	    /// The value of `migratable` determines whether footnotes within the float
293	    /// should be allowed to prompt its migration if they don't fit in order to
294	    /// respect the footnote invariant (entries in the same page as the
295	    /// references), triggering [`Stop::Finish`]. This is usually `true` within
296	    /// the distributor, as it can handle that particular flow event, and
297	    /// `false` elsewhere.
298	    pub fn float(
299	        &mut self,
300	        placed: &'b PlacedChild<'a>,
301	        regions: &Regions,
302	        clearance: bool,
303	        migratable: bool,
304	    ) -> FlowResult<()> {
305	        // If the float is already processed, skip it.
306	        let loc = placed.location();
307	        if self.skipped(loc) {
308	            return Ok(());
309	        }
310	
311	        // If there is already a queued float, queue this one as well. We
312	        // don't want to disrupt the order.
313	        if !self.work.floats.is_empty() {
314	            self.work.floats.push(placed);
315	            return Ok(());
316	        }
317	
318	        // Determine the base size of the chosen scope.
319	        let base = match placed.scope {
320	            PlacementScope::Column => regions.base(),
321	            PlacementScope::Parent => self.page_base,
322	        };
323	
324	        // Lay out the placed element.
325	        let frame = placed.layout(self.engine, base)?;
326	
327	        // Determine the remaining space in the scope. This is exact for column
328	        // placement, but only an approximation for page placement.
329	        let remaining = match placed.scope {
330	            PlacementScope::Column => regions.size.y,
331	            PlacementScope::Parent => {
332	                let remaining: Abs = regions
333	                    .iter()
334	                    .map(|size| size.y)
335	                    .take(self.config.columns.count - self.column)
336	                    .sum();
337	                remaining / self.config.columns.count as f64
338	            }
339	        };
340	
341	        // We only require clearance if there is other content.
342	        let clearance = if clearance { placed.clearance } else { Abs::zero() };
343	        let need = frame.height() + clearance;
344	
345	        // If the float doesn't fit, queue it for the next region.
346	        if !remaining.fits(need) && regions.may_progress() {
347	            self.work.floats.push(placed);
348	            return Ok(());
349	        }
350	
351	        // Handle footnotes in the float.
352	        self.footnotes(regions, &frame, need, false, migratable)?;
353	
354	        // Determine the float's vertical alignment. We can unwrap the inner
355	        // `Option` because `Custom(None)` is checked for during collection.
356	        let align_y = placed.align_y.map(Option::unwrap).unwrap_or_else(|| {
357	            // When the float's vertical midpoint would be above the middle of
358	            // the page if it were layouted in-flow, we use top alignment.
359	            // Otherwise, we use bottom alignment.
360	            let used = base.y - remaining;
361	            let half = need / 2.0;
362	            let ratio = (used + half) / base.y;
363	            if ratio <= 0.5 { FixedAlignment::Start } else { FixedAlignment::End }
364	        });
365	
366	        // Select the insertion area where we'll put this float.
367	        let area = match placed.scope {
368	            PlacementScope::Column => &mut self.column_insertions,
369	            PlacementScope::Parent => &mut self.page_insertions,
370	        };
371	
372	        // Put the float there.
373	        area.push_float(placed, frame, align_y);
374	        area.skips.push(loc);
375	
376	        // Trigger relayout.
377	        Err(Stop::Relayout(placed.scope))
378	    }
379	
380	    /// Lays out footnotes in the `frame` if this is the root flow and there are
381	    /// any. The value of `breakable` indicates whether the element that
382	    /// produced the frame is breakable. If not, the frame is treated as atomic.
383	    ///
384	    /// The value of `migratable` indicates whether footnote migration should be
385	    /// possible (at least for the first footnote found in the frame, as it is
386	    /// forbidden for the second footnote onwards). It is usually `true` within
387	    /// the distributor and `false` elsewhere, as the distributor can handle
388	    /// [`Stop::Finish`] which is returned when migration is requested.
389	    pub fn footnotes(
390	        &mut self,
391	        regions: &Regions,
392	        frame: &Frame,
393	        flow_need: Abs,
394	        breakable: bool,
395	        migratable: bool,
396	    ) -> FlowResult<()> {
397	        // Footnotes are only supported at the root level.
398	        if self.config.mode != FlowMode::Root {
399	            return Ok(());
400	        }
401	
402	        // Search for footnotes.
403	        let mut notes = vec![];
404	        for tag in &self.work.tags {
405	            let Tag::Start(elem, _) = tag else { continue };
406	            let Some(note) = elem.to_packed::<FootnoteElem>() else { continue };
407	            notes.push((Abs::zero(), note.clone()));
408	        }
409	        find_in_frame_impl::<FootnoteElem>(&mut notes, frame, Abs::zero());
410	        if notes.is_empty() {
411	            return Ok(());
412	        }
413	
414	        let mut relayout = false;
415	        let mut regions = *regions;
416	
417	        // The first footnote's origin frame should be migratable if the region
418	        // may progress (already checked by the footnote function) and if the
419	        // origin frame isn't breakable (checked here).
420	        let mut migratable = migratable && !breakable;
421	
422	        for (y, elem) in notes {
423	            // The amount of space used by the in-flow content that contains the
424	            // footnote marker. For a breakable frame, it's the y position of
425	            // the marker. For an unbreakable frame, it's the full height.
426	            let flow_need = if breakable { y } else { flow_need };
427	
428	            // Process the footnote.
429	            match self.footnote(elem, &mut regions, flow_need, migratable) {
430	                // The footnote was already processed or queued.
431	                Ok(()) => {}
432	                // First handle more footnotes before relayouting.
433	                Err(Stop::Relayout(_)) => relayout = true,
434	                // Either of
435	                // - A `Stop::Finish` indicating that the frame's origin element
436	                //   should migrate to uphold the footnote invariant.
437	                // - A fatal error.
438	                err => return err,
439	            }
440	
441	            // We only migrate the origin frame if the first footnote's first
442	            // line didn't fit.
443	            migratable = false;
444	        }
445	
446	        // If this is set, we laid out at least one footnote, so we need a
447	        // relayout.
448	        if relayout {
449	            return Err(Stop::Relayout(PlacementScope::Column));
450	        }
451	
452	        Ok(())
453	    }
454	
455	    /// Handles a single footnote.
456	    fn footnote(
457	        &mut self,
458	        elem: Packed<FootnoteElem>,
459	        regions: &mut Regions,
460	        flow_need: Abs,
461	        migratable: bool,
462	    ) -> FlowResult<()> {
463	        // Ignore reference footnotes and already processed ones.
464	        let loc = elem.location().unwrap();
465	        if elem.is_ref() || self.skipped(loc) {
466	            return Ok(());
467	        }
468	
469	        // If there is already a queued spill or footnote, queue this one as
470	        // well. We don't want to disrupt the order.
471	        let area = &mut self.column_insertions;
472	        if self.footnote_spill.is_some() || !self.footnote_queue.is_empty() {
473	            self.footnote_queue.push(elem);
474	            return Ok(());
475	        }
476	
477	        // If there weren't any footnotes so far, account for the footnote
478	        // separator.
479	        let mut separator = None;
480	        let mut separator_need = Abs::zero();
481	        if area.footnotes.is_empty() {
482	            let frame =
483	                layout_footnote_separator(self.engine, self.config, regions.base())?;
484	            separator_need += self.config.footnote.clearance + frame.height();
485	            separator = Some(frame);
486	        }
487	
488	        // Prepare regions for the footnote.
489	        let mut pod = *regions;
490	        pod.expand.y = false;
491	        pod.size.y -= flow_need + separator_need + self.config.footnote.gap;
492	
493	        // Layout the footnote entry.
494	        let frames = layout_footnote(self.engine, self.config, &elem, pod)?.into_frames();
495	
496	        // Find nested footnotes in the entry.
497	        let nested = find_in_frames::<FootnoteElem>(&frames);
498	
499	        // Check if there are any non-empty frames.
500	        let exist_non_empty_frame = frames.iter().any(|f| !f.is_empty());
501	
502	        // Extract the first frame.
503	        let mut iter = frames.into_iter();
504	        let first = iter.next().unwrap();
505	        let note_need = self.config.footnote.gap + first.height();
506	
507	        // If the first frame is empty, then none of its content fit. If
508	        // possible, we then migrate the origin frame to the next region to
509	        // uphold the footnote invariant (that marker and entry are on the same
510	        // page). If not, we just queue the footnote for the next page, but
511	        // only if that would actually make a difference (that is, if the
512	        // footnote isn't alone in the page after not fitting in any previous
513	        // pages, as it probably won't ever fit then).
514	        //
515	        // Note that a non-zero flow need also indicates that queueing would
516	        // make a difference, because the flow need is subtracted from the
517	        // available height in the entry's pod even if what caused that need
518	        // wasn't considered for the input `regions`. For example, floats just
519	        // pass the `regions` they received along to their footnotes, which
520	        // don't take into account the space occupied by the floats themselves,
521	        // but they do indicate their footnotes have a non-zero flow need, so
522	        // queueing them can matter as, in the following pages, the flow need
523	        // will be set to zero and the footnote will be alone in the page.
524	        // Then, `may_progress()` will also be false (this time, correctly) and
525	        // the footnote is laid out, as queueing wouldn't improve the lack of
526	        // space anymore and would result in an infinite loop.
527	        //
528	        // However, it is worth noting that migration does take into account
529	        // the original region, before inserting what prompted the flow need.
530	        // Logically, if moving the original frame can't improve the lack of
531	        // space, then migration should be inhibited. The space occupied by the
532	        // original frame is not relevant for that check. Therefore,
533	        // `regions.may_progress()` must still be checked separately for
534	        // migration, regardless of the presence of flow need.
535	        if first.is_empty() && exist_non_empty_frame {
536	            if migratable && regions.may_progress() {
537	                return Err(Stop::Finish(false));
538	            } else if regions.may_progress() || !flow_need.is_zero() {
539	                self.footnote_queue.push(elem);
540	                return Ok(());
541	            }
542	        }
543	
544	        // Save the separator.
545	        if let Some(frame) = separator {
546	            area.push_footnote_separator(self.config, frame);
547	            regions.size.y -= separator_need;
548	        }
549	
550	        // Save the footnote's frame.
551	        area.push_footnote(self.config, first);
552	        area.skips.push(loc);
553	        regions.size.y -= note_need;
554	
555	        // Save the spill.
556	        if !iter.as_slice().is_empty() {
557	            self.footnote_spill = Some(iter);
558	        }
559	
560	        // Lay out nested footnotes.
561	        for (_, note) in nested {
562	            match self.footnote(note, regions, flow_need, migratable) {
563	                // This footnote was already processed or queued.
564	                Ok(()) => {}
565	                // Footnotes always request a relayout when processed for the
566	                // first time, so we ignore a relayout request since we're
567	                // about to do so afterwards. Without this check, the first
568	                // inner footnote interrupts processing of the following ones.
569	                Err(Stop::Relayout(_)) => {}
570	                // Either of
571	                // - A `Stop::Finish` indicating that the frame's origin element
572	                //   should migrate to uphold the footnote invariant.
573	                // - A fatal error.
574	                err => return err,
575	            }
576	        }
577	
578	        // Since we laid out a footnote, we need a relayout.
579	        Err(Stop::Relayout(PlacementScope::Column))
580	    }
581	
582	    /// Handles spillover from a footnote.
583	    fn footnote_spill(
584	        &mut self,
585	        mut iter: std::vec::IntoIter<Frame>,
586	        base: Size,
587	    ) -> SourceResult<()> {
588	        let area = &mut self.column_insertions;
589	
590	        // Create and save the separator.
591	        let separator = layout_footnote_separator(self.engine, self.config, base)?;
592	        area.push_footnote_separator(self.config, separator);
593	
594	        // Save the footnote's frame.
595	        let frame = iter.next().unwrap();
596	        area.push_footnote(self.config, frame);
597	
598	        // Save the spill.
599	        if !iter.as_slice().is_empty() {
600	            self.footnote_spill = Some(iter);
601	        }
602	
603	        Ok(())
604	    }
