229	        }
230	    }
231	
232	    /// Collect a block into a [`SingleChild`] or [`MultiChild`] depending on
233	    /// whether it is breakable.
234	    fn block(&mut self, elem: &'a Packed<BlockElem>, styles: StyleChain<'a>) {
235	        let locator = self.locator.next(&elem.span());
236	        let align = styles.resolve(AlignElem::alignment);
237	        let alone = self.children.len() == 1;
238	        let sticky = elem.sticky.get(styles);
239	        let breakable = elem.breakable.get(styles);
240	        let fr = match elem.height.get(styles) {
241	            Sizing::Fr(fr) => Some(fr),
242	            _ => None,
243	        };
244	
245	        let fallback = LazyCell::new(|| styles.resolve(ParElem::spacing));
246	        let spacing = |amount| match amount {
247	            Smart::Auto => Child::Rel((*fallback).into(), 4),
248	            Smart::Custom(Spacing::Rel(rel)) => Child::Rel(rel.resolve(styles), 3),
249	            Smart::Custom(Spacing::Fr(fr)) => Child::Fr(fr, 2),
250	        };
251	
252	        self.output.push(spacing(elem.above.get(styles)));
253	
254	        if !breakable || fr.is_some() {
255	            self.output.push(Child::Single(self.boxed(SingleChild {
256	                align,
257	                sticky,
258	                alone,
259	                fr,
260	                elem,
261	                styles,
262	                locator,
263	                cell: CachedCell::new(),
264	            })));
265	        } else {
266	            self.output.push(Child::Multi(self.boxed(MultiChild {
267	                align,
268	                sticky,
269	                alone,
270	                elem,
271	                styles,
272	                locator,
273	                cell: CachedCell::new(),
274	            })));
275	        }
276	
277	        self.output.push(spacing(elem.below.get(styles)));
278	        self.par_situation = ParSituation::Other;
279	    }
280	
281	    /// Collects a placed element into a [`PlacedChild`].
282	    fn place(
283	        &mut self,
284	        elem: &'a Packed<PlaceElem>,
285	        styles: StyleChain<'a>,
286	    ) -> SourceResult<()> {
287	        let alignment = elem.alignment.get(styles);
288	        let align_x = alignment.map_or(FixedAlignment::Center, |align| {
289	            align.x().unwrap_or_default().resolve(styles)
290	        });
291	        let align_y = alignment.map(|align| align.y().map(|y| y.resolve(styles)));
292	        let scope = elem.scope.get(styles);
293	        let float = elem.float.get(styles);
294	
295	        match (float, align_y) {
296	            (true, Smart::Custom(None | Some(FixedAlignment::Center))) => bail!(
297	                elem.span(),
298	                "vertical floating placement must be `auto`, `top`, or `bottom`"
299	            ),
300	            (false, Smart::Auto) => bail!(
301	                elem.span(),
302	                "automatic positioning is only available for floating placement";
303	                hint: "you can enable floating placement with `place(float: true, ..)`";
304	            ),
305	            _ => {}
306	        }
307	
308	        if !float && scope == PlacementScope::Parent {
309	            bail!(
310	                elem.span(),
311	                "parent-scoped positioning is currently only available for floating placement";
312	                hint: "you can enable floating placement with `place(float: true, ..)`";
313	            );
314	        }
315	
316	        let locator = self.locator.next(&elem.span());
317	        let clearance = elem.clearance.resolve(styles);
318	        let delta = Axes::new(elem.dx.get(styles), elem.dy.get(styles)).resolve(styles);
319	        self.output.push(Child::Placed(self.boxed(PlacedChild {
320	            align_x,
321	            align_y,
322	            scope,
323	            float,
324	            clearance,
325	            delta,
326	            elem,
327	            styles,
328	            locator,
329	            alignment,
330	            cell: CachedCell::new(),
331	        })));
332	
333	        Ok(())
334	    }
335	
336	    /// Wraps a value in a bump-allocated box to reduce its footprint in the
337	    /// [`Child`] enum.
338	    fn boxed<T>(&self, value: T) -> BumpBox<'a, T> {
339	        BumpBox::new_in(value, self.bump)
340	    }
341	}
