411	/// The cached, internal implementation of [`SingleChild::layout`].
412	#[comemo::memoize]
413	#[expect(clippy::too_many_arguments)]
414	fn layout_single_impl(
415	    world: Tracked<dyn World + '_>,
416	    library: &LazyHash<Library>,
417	    introspector: Tracked<dyn Introspector + '_>,
418	    traced: Tracked<Traced>,
