623	    pub align_x: FixedAlignment,
624	    pub align_y: Smart<Option<FixedAlignment>>,
625	    pub scope: PlacementScope,
626	    pub float: bool,
627	    pub clearance: Abs,
628	    pub delta: Axes<Rel<Abs>>,
629	    elem: &'a Packed<PlaceElem>,
630	    styles: StyleChain<'a>,
631	    locator: Locator<'a>,
632	    alignment: Smart<Alignment>,
633	    cell: CachedCell<SourceResult<Frame>>,
634	}
