636	impl PlacedChild<'_> {
637	    /// Build the child's frame given the region's base size.
638	    pub fn layout(&self, engine: &mut Engine, base: Size) -> SourceResult<Frame> {
639	        self.cell.get_or_init(base, |base| {
640	            let align = self.alignment.unwrap_or_else(|| Alignment::CENTER);
641	            let aligned = AlignElem::alignment.set(align).wrap();
642	            let styles = self.styles.chain(&aligned);
643	
644	            let mut frame = layout_and_modify(styles, |styles| {
645	                crate::layout_frame(
646	                    engine,
647	                    &self.elem.body,
648	                    self.locator.relayout(),
649	                    styles,
650	                    Region::new(base, Axes::splat(false)),
651	                )
652	            })?;
653	
654	            if self.float {
655	                frame.set_parent(FrameParent::new(
656	                    self.elem.location().unwrap(),
657	                    Inherit::Yes,
658	                ));
659	            }
660	
661	            Ok(frame)
662	        })
663	    }
664	
665	    /// The element's location.
666	    pub fn location(&self) -> Location {
667	        self.elem.location().unwrap()
668	    }
669	}
670	
671	/// Wraps a parameterized computation and caches its latest output.
672	///
673	/// - When the computation is performed multiple times consecutively with the
674	///   same argument, reuses the cache.
675	/// - When the argument changes, the new output is cached.
676	#[derive(Clone)]
677	struct CachedCell<T>(RefCell<Option<(u128, T)>>);
678	
679	impl<T> CachedCell<T> {
680	    /// Create an empty cached cell.
681	    fn new() -> Self {
682	        Self(RefCell::new(None))
683	    }
684	
685	    /// Perform the computation `f` with caching.
686	    fn get_or_init<F, I>(&self, input: I, f: F) -> T
687	    where
688	        I: Hash,
689	        T: Clone,
690	        F: FnOnce(I) -> T,
691	    {
692	        let input_hash = typst_utils::hash128(&input);
693	
694	        let mut slot = self.0.borrow_mut();
695	        if let Some((hash, output)) = &*slot
696	            && *hash == input_hash
697	        {
698	            return output.clone();
699	        }
700	
701	        let output = f(input);
702	        *slot = Some((input_hash, output.clone()));
703	        output
704	    }
705	}
706	
707	impl<T> Default for CachedCell<T> {
708	    fn default() -> Self {
709	        Self::new()
710	    }
711	}
712	
713	impl<T> Debug for CachedCell<T> {
714	    fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
715	        f.pad("CachedCell(..)")
716	    }
717	}
