12	/// Distributes as many children as fit from `composer.work` into the first
13	/// region and returns the resulting frame and the height actually used
14	/// by the inner contents (for column balancing).
15	pub fn distribute(
16	    composer: &mut Composer,
17	    regions: Regions,
18	    balancing_target: Option<Abs>,
19	) -> FlowResult<(Frame, Abs)> {
20	    let mut distributor = Distributor {
21	        composer,
22	        regions,
23	        items: vec![],
24	        used: Size::zero(),
25	        target: balancing_target,
26	        sticky: None,
