30	    let forced = match distributor.run() {
31	        Ok(()) => distributor.composer.work.done(),
32	        Err(Stop::Finish(forced)) => forced,
33	        Err(err) => return Err(err),
34	    };
35	    let region = Region::new(regions.size, regions.expand);
36	    distributor.finalize(region, init, forced)
