205	            match *item {
206	                // When previous weak relative spacing exists that's at most as
207	                // weak, we reuse the old item, set it to the maximum of both,
208	                // and discard the new item.
209	                Item::Abs(prev_amount, prev_weakness @ 1..) => {
210	                    if weakness <= prev_weakness
211	                        && (weakness < prev_weakness || amount > prev_amount)
212	                    {
213	                        *item = Item::Abs(amount, weakness);
214	                        self.use_height(amount - prev_amount);
215	                    }
216	                    return false;
217	                }
218	                // These are "peeked beyond" for spacing collapsing purposes.
219	                Item::Tag(_) | Item::Abs(_, 0) | Item::Placed(..) => {}
220	                // Any kind of fractional spacing destructs weak relative
221	                // spacing.
222	                Item::Fr(.., None) => return false,
223	                // These naturally support the spacing.
224	                Item::Frame(..) | Item::Fr(.., Some(_)) => return true,
225	            }
226	        }
227	        false
228	    }
229	
230	    /// Decides whether to keep weak fractional spacing based on previous items.
231	    /// If there is a preceding weak spacing, it might be patched in place.
232	    fn keep_weak_fr_spacing(&mut self, fr: Fr, weakness: u8) -> bool {
233	        for item in self.items.iter_mut().rev() {
234	            match *item {
235	                // When previous weak fr spacing exists that's at most as weak,
236	                // we reuse the old item, set it to the maximum of both, and
237	                // discard the new item.
238	                Item::Fr(prev_fr, prev_weakness @ 1.., None) => {
239	                    if weakness <= prev_weakness
240	                        && (weakness < prev_weakness || fr > prev_fr)
241	                    {
242	                        *item = Item::Fr(fr, weakness, None);
243	                    }
244	                    return false;
245	                }
246	                // These are "peeked beyond" for spacing collapsing purposes.
247	                // Weak absolute spacing, in particular, will be trimmed once
248	                // we push the fractional spacing.
249	                Item::Tag(_) | Item::Abs(..) | Item::Placed(..) => {}
250	                // For weak + strong fr spacing, we keep both, same as for
251	                // weak + strong rel spacing.
252	                Item::Fr(.., None) => return true,
253	                // These naturally support the spacing.
254	                Item::Frame(..) | Item::Fr(.., Some(_)) => return true,
255	            }
256	        }
257	        false
258	    }
259	
260	    /// Trims trailing weak spacing from the items.
261	    fn trim_spacing(&mut self) {
262	        for (i, item) in self.items.iter().enumerate().rev() {
263	            match *item {
264	                Item::Abs(amount, 1..) => {
265	                    self.use_height(-amount);
266	                    self.items.remove(i);
267	                    break;
268	                }
269	                Item::Fr(_, 1.., None) => {
270	                    self.items.remove(i);
271	                    break;
272	                }
273	                Item::Tag(_) | Item::Abs(..) | Item::Placed(..) => {}
274	                Item::Frame(..) | Item::Fr(..) => break,
275	            }
276	        }
277	    }
278	
279	    /// The amount of trailing weak spacing.
280	    fn weak_spacing(&mut self) -> Abs {
281	        for item in self.items.iter().rev() {
282	            match *item {
283	                Item::Abs(amount, 1..) => return amount,
284	                Item::Tag(_) | Item::Abs(..) | Item::Placed(..) => {}
285	                Item::Frame(..) | Item::Fr(..) => break,
286	            }
287	        }
288	        Abs::zero()
289	    }
290	
291	    /// Whether the amount fits into the remaining region, taking into account
292	    /// column balancing limits.
293	    pub fn fits(&self, amount: Abs) -> bool {
294	        self.regions.size.y.fits(amount)
295	            && self
296	                .target
297	                // Add elements as long as the balancing target is not reached. By not including
298	                // the amount itself here, we avoid protruding items to cumulate in the last column.
299	                .is_none_or(|target| target.fits(self.used.y))
300	    }
301	
302	    /// Processes a line of a paragraph.
303	    fn line(&mut self, line: &'b LineChild) -> FlowResult<()> {
304	        // If the line doesn't fit and a followup region may improve things,
305	        // finish the region.
306	        if !self.fits(line.frame.height()) && self.regions.may_progress() {
307	            return Err(Stop::Finish(false));
308	        }
309	
310	        // If the line's need, which includes its own height and that of
311	        // following lines grouped by widow/orphan prevention, does not fit into
312	        // the current region, but does fit into the next region, finish the
313	        // region.
314	        if !self.fits(line.need)
315	            && self
316	                .regions
317	                .iter()
318	                .nth(1)
319	                .is_some_and(|region| region.y.fits(line.need))
320	        {
321	            return Err(Stop::Finish(false));
322	        }
323	
324	        self.frame(line.frame.clone(), line.align, false, false)
325	    }
326	
327	    /// Processes an unbreakable block.
328	    fn single(&mut self, single: &'b SingleChild<'a>) -> FlowResult<()> {
329	        // Lay out the block.
330	        let frame = single.layout(
331	            self.composer.engine,
332	            Region::new(self.regions.base(), self.regions.expand),
333	        )?;
334	
335	        // Handle fractionally sized blocks.
336	        if let Some(fr) = single.fr {
337	            self.composer
338	                .footnotes(&self.regions, &frame, Abs::zero(), false, true)?;
339	            self.flush_tags();
340	            self.items.push(Item::Fr(fr, 0, Some(single)));
341	            return Ok(());
342	        }
343	
344	        // If the block doesn't fit and a followup region may improve things,
345	        // finish the region.
346	        if !self.fits(frame.height()) && self.regions.may_progress() {
347	            return Err(Stop::Finish(false));
348	        }
349	
350	        self.frame(frame, single.align, single.sticky, false)
351	    }
352	
353	    /// Processes a breakable block.
354	    fn multi(&mut self, multi: &'b MultiChild<'a>) -> FlowResult<()> {
355	        let mut pod = self.regions;
356	
357	        // For column balancing, reduce the region size for layout.
358	        if let Some(lim) = self.target {
359	            let remaining = lim - self.used.y;
360	            pod.size.y.set_min(remaining);
361	        }
362	
363	        // Skip directly if the region is already (over)full. `line` and
364	        // `single` implicitly do this through their `fits` checks.
365	        if pod.is_full() {
366	            return Err(Stop::Finish(false));
367	        }
368	
369	        // Lay out the block.
370	        let (frame, spill) = multi.layout(self.composer.engine, pod)?;
371	        if frame.is_empty()
372	            && spill.as_ref().is_some_and(|s| s.exist_non_empty_frame)
373	            && self.regions.may_progress()
374	        {
375	            // If the first frame is empty, but there are non-empty frames in
376	            // the spill, the whole child should be put in the next region to
377	            // avoid any invisible orphans at the end of this region.
378	            return Err(Stop::Finish(false));
379	        }
380	
381	        self.frame(frame, multi.align, multi.sticky, true)?;
382	
383	        // If the block didn't fully fit into the current region, save it into
384	        // the `spill` and finish the region.
385	        if let Some(spill) = spill {
386	            self.composer.work.spill = Some(spill);
387	            self.composer.work.advance();
388	            return Err(Stop::Finish(false));
389	        }
390	
391	        Ok(())
392	    }
393	
394	    /// Processes spillover from a breakable block.
395	    fn multi_spill(&mut self, spill: MultiSpill<'a, 'b>) -> FlowResult<()> {
396	        let mut pod = self.regions;
397	
398	        // For column balancing, reduce the region size for layout.
399	        if let Some(lim) = self.target {
400	            let remaining = lim - self.used.y;
401	            pod.size.y.set_min(remaining);
402	        }
403	
404	        // Skip directly if the region is already (over)full.
405	        if pod.is_full() {
406	            self.composer.work.spill = Some(spill);
407	            return Err(Stop::Finish(false));
408	        }
409	
410	        // Lay out the spilled remains.
411	        let align = spill.align();
412	        let (frame, spill) = spill.layout(self.composer.engine, pod)?;
413	        self.frame(frame, align, false, true)?;
414	
415	        // If there's still more, save it into the `spill` and finish the
416	        // region.
417	        if let Some(spill) = spill {
418	            self.composer.work.spill = Some(spill);
419	            return Err(Stop::Finish(false));
420	        }
421	
422	        Ok(())
423	    }
424	
425	    /// Processes an in-flow frame, generated from a line or block.
426	    fn frame(
427	        &mut self,
428	        frame: Frame,
429	        align: Axes<FixedAlignment>,
430	        sticky: bool,
431	        breakable: bool,
432	    ) -> FlowResult<()> {
433	        // If the frame is sticky and we haven't remembered a preceding sticky
434	        // element, make a checkpoint which we can restore should we end on
435	        // this sticky element.
436	        //
437	        // The first sticky block within consecutive sticky blocks determines
438	        // whether this group of sticky blocks has stickiness disabled or not.
439	        //
440	        // The criteria used here is: if migrating this group of sticky blocks
441	        // together with the "attached" block can't improve the lack of space,
442	        // since we're at the start of the region, then we don't do so, and
443	        // stickiness is disabled (at least, for this region). Otherwise,
444	        // migration is allowed.
445	        //
446	        // Note that, since the whole region is checked, this ensures sticky
447	        // blocks at the top of a block - but not necessarily of the page - can
448	        // still be migrated.
449	        if sticky
450	            && self.sticky.is_none()
451	            && *self.stickable.get_or_insert_with(|| self.regions.may_progress())
452	        {
453	            self.sticky = Some(self.snapshot());
454	        }
455	
456	        // Handle footnotes.
457	        //
458	        // This must happen before we forget a previous sticky snapshot below.
459	        // If a non-sticky frame's footnote doesn't fit, the frame and any
460	        // preceding sticky blocks attached to it need to migrate to the next
461	        // region together. Resetting the sticky state first would then strand
462	        // those sticky blocks in this region.
463	        self.composer.footnotes(
464	            &self.regions,
465	            &frame,
466	            frame.height(),
467	            breakable,
468	            true,
469	        )?;
470	
471	        if !sticky && !frame.is_empty() {
472	            // If the frame isn't sticky, we can forget a previous snapshot. We
473	            // interrupt a group of sticky blocks, if there was one, so we reset
474	            // the saved stickable check for the next group of sticky blocks.
475	            self.sticky = None;
476	            self.stickable = None;
477	        }
478	
479	        // Push an item for the frame.
480	        self.use_height(frame.height());
481	        self.used.x.set_max(frame.width());
482	        self.flush_tags();
483	        self.items.push(Item::Frame(frame, align));
484	        Ok(())
485	    }
486	
487	    /// Processes an absolutely or floatingly placed child.
488	    fn placed(&mut self, placed: &'b PlacedChild<'a>) -> FlowResult<()> {
489	        if placed.float {
490	            // If the element is floatingly placed, let the composer handle it.
491	            // It might require relayout because the area available for
492	            // distribution shrinks. We make the spacing occupied by weak
493	            // spacing temporarily available again because it can collapse if it
494	            // ends up at a break due to the float.
495	            let weak_spacing = self.weak_spacing();
496	            self.use_height(-weak_spacing);
497	            self.composer.float(
498	                placed,
499	                &self.regions,
500	                self.items.iter().any(|item| matches!(item, Item::Frame(..))),
501	                true,
502	            )?;
503	            self.use_height(weak_spacing);
504	        } else {
505	            let frame = placed.layout(self.composer.engine, self.regions.base())?;
506	            self.composer
507	                .footnotes(&self.regions, &frame, Abs::zero(), true, true)?;
508	            self.flush_tags();
509	            self.items.push(Item::Placed(frame, placed));
510	        }
511	        Ok(())
512	    }
513	
514	    /// Processes a float flush.
515	    fn flush(&mut self) -> FlowResult<()> {
516	        // If there are still pending floats, finish the region instead of
517	        // adding more content to it.
518	        if !self.composer.work.floats.is_empty() {
519	            return Err(Stop::Finish(false));
520	        }
521	        Ok(())
522	    }
523	
524	    /// Processes a column break.
525	    fn break_(&mut self, weak: bool) -> FlowResult<()> {
526	        // If there is a region to break into, break into it.
527	        if (!weak || !self.items.is_empty())
528	            && (!self.regions.backlog.is_empty() || self.regions.last.is_some())
529	        {
530	            self.composer.work.advance();
531	            return Err(Stop::Finish(true));
532	        }
533	        Ok(())
534	    }
535	
536	    /// Arranges the produced items into an output frame.
537	    ///
538	    /// This performs alignment and resolves fractional spacing and blocks.
539	    fn finalize(
540	        mut self,
541	        region: Region,
542	        init: DistributionSnapshot<'a, 'b>,
543	        forced: bool,
544	    ) -> FlowResult<(Frame, Abs)> {
545	        if forced {
546	            // If this is the very end of the flow, flush pending tags.
547	            self.flush_tags();
548	        } else if !self.items.is_empty() && self.items.iter().all(Item::migratable) {
549	            // Restore the initial state of all items are migratable.
550	            self.restore(init);
551	        } else {
552	            // If we ended on a sticky block, but are not yet at the end of
553	            // the flow, restore the saved checkpoint to move the sticky
554	            // suffix to the next region.
555	            if let Some(snapshot) = self.sticky.take() {
556	                self.restore(snapshot);
557	            }
558	        }
559	
560	        self.trim_spacing();
561	
562	        let used_height_without_fr = self.used.y;
563	
564	        // Determine the sum of fractionals.
565	        let mut frs = Fr::zero();
566	        let mut has_fr_child = false;
567	        for item in &self.items {
568	            if let Item::Fr(v, _, child) = item {
569	                frs += *v;
570	                has_fr_child |= child.is_some();
571	            }
572	        }
573	
574	        // When we have fractional spacing, occupy the remaining space with it.
575	        let mut fr_space = Abs::zero();
576	        if frs.get() > 0.0 && region.size.y.is_finite() {
577	            fr_space = region.size.y - self.used.y;
578	            self.used.y = region.size.y;
579	        }
580	
581	        // Lay out fractionally sized blocks.
582	        let mut fr_frames = vec![];
583	        if has_fr_child {
584	            for item in &self.items {
585	                let Item::Fr(v, _, Some(single)) = item else { continue };
586	                let length = v.share(frs, fr_space);
587	                let pod = Region::new(Size::new(region.size.x, length), region.expand);
588	                let frame = single.layout(self.composer.engine, pod)?;
589	                self.used.x.set_max(frame.width());
590	                fr_frames.push(frame);
591	            }
592	        }
593	
594	        // Also consider the width of insertions for alignment.
595	        if !region.expand.x {
596	            self.used.x.set_max(self.composer.insertion_width());
597	        }
598	
599	        // Determine the region's size.
600	        let size = region.expand.select(region.size, self.used.min(region.size));
601	        let free = size.y - self.used.y;
602	
603	        let mut output = Frame::soft(size);
604	        let mut ruler = FixedAlignment::Start;
605	        let mut offset = Abs::zero();
606	        let mut fr_frames = fr_frames.into_iter();
607	
608	        // Position all items.
609	        let mut baseline_set = false;
610	        for item in self.items {
611	            match item {
612	                Item::Tag(tag) => {
613	                    let y = offset + ruler.position(free);
614	                    let pos = Point::with_y(y);
615	                    output.push(pos, FrameItem::Tag(tag.clone()));
616	                }
617	                Item::Abs(v, _) => {
618	                    offset += v;
619	                }
620	                Item::Fr(v, _, single) => {
621	                    let length = v.share(frs, fr_space);
622	                    if let Some(single) = single {
623	                        let frame = fr_frames.next().unwrap();
624	                        let x = single.align.x.position(size.x - frame.width());
625	                        let pos = Point::new(x, offset);
626	                        output.push_frame(pos, frame);
627	                    }
628	                    offset += length;
629	                }
630	                Item::Frame(frame, align) => {
631	                    ruler = ruler.max(align.y);
632	
633	                    let x = align.x.position(size.x - frame.width());
634	                    let y = offset + ruler.position(free);
635	                    let pos = Point::new(x, y);
636	                    offset += frame.height();
637	
638	                    // The baseline of the whole region will be the set to the
639	                    // baseline of the first in-flow frame. For example, of the
640	                    // first paragraph, if there is more than one. But also,
641	                    // inside the paragraph itself, this will be the first line
642	                    // (since each line is laid out as a separate frame).
643	                    if !baseline_set {
644	                        if frame.has_baseline() {
645	                            output.set_baseline(y + frame.baseline());
646	                        }
647	                        baseline_set = true;
648	                    }
649	
650	                    output.push_frame(pos, frame);
651	                }
652	                Item::Placed(frame, placed) => {
653	                    let x = placed.align_x.position(size.x - frame.width());
654	                    let y = match placed.align_y.unwrap_or_default() {
655	                        Some(align) => align.position(size.y - frame.height()),
656	                        _ => offset + ruler.position(free),
657	                    };
658	
659	                    let pos = Point::new(x, y)
660	                        + placed.delta.zip_map(size, Rel::relative_to).to_point();
661	
662	                    output.push_frame(pos, frame);
663	                }
664	            }
665	        }
666	
667	        Ok((output, used_height_without_fr))
668	    }
669	
670	    /// Create a snapshot of the work and items.
671	    fn snapshot(&self) -> DistributionSnapshot<'a, 'b> {
672	        DistributionSnapshot {
673	            work: self.composer.work.clone(),
674	            items: self.items.len(),
675	            used: self.used,
676	        }
677	    }
678	
679	    /// Restore a snapshot of the work and items.
680	    fn restore(&mut self, snapshot: DistributionSnapshot<'a, 'b>) {
681	        *self.composer.work = snapshot.work;
682	        self.items.truncate(snapshot.items);
683	        self.used = snapshot.used;
684	    }
685	}
